/* A local simulation only. This module never calls Google or opens an OAuth page. */
const demoBusy = [
  {id:'class-1',day:17,start:840,end:915,title:'Marketing lecture',place:'Business school · Demo class'},
  {id:'class-2',day:18,start:960,end:1020,title:'MIS 430 project meeting',place:'Library · Demo group'},
  {id:'class-3',day:19,start:660,end:735,title:'Statistics lecture',place:'Classroom · Demo class'},
  {id:'class-4',day:20,start:900,end:960,title:'Study group',place:'Library · Demo group'},
  {id:'class-5',day:21,start:540,end:600,title:'Coffee with a friend',place:'Campus café · Demo plan'}
];
const eventMinutes={1:[1050,1140],2:[990,1050],3:[1080,1200],4:[900,990],5:[600,690],6:[840,960]};
const emptyCalendar=()=>({connected:false,added:[]});
let calendarState=emptyCalendar();
try {
  const cached=JSON.parse(localStorage.getItem('socialfinder-calendar-v1'));
  if(cached?.connected===true)calendarState={connected:true,added:Array.isArray(cached.added)?[...new Set(cached.added.filter(id=>Number.isInteger(id)&&Object.hasOwn(eventMinutes,id)))]:[]};
} catch {}
let calendarStorageOK=true;
function persistCalendar(){try{localStorage.setItem('socialfinder-calendar-v1',JSON.stringify(calendarState));calendarStorageOK=true}catch{calendarStorageOK=false}}
function resetCalendar(){calendarState=emptyCalendar();persistCalendar()}
function calendarNotice(message){toast(message+(calendarStorageOK?'':' Calendar changes last for this visit only; browser storage is unavailable.'))}
function formatMinute(value){const h=Math.floor(value/60);return `${h%12||12}:${String(value%60).padStart(2,'0')} ${h>=12?'PM':'AM'}`}
function intervalsOverlap(a,b){return a.day===b.day&&a.start<b.end&&b.start<a.end}
function calendarEvent(e){return {...e,start:eventMinutes[e.id][0],end:eventMinutes[e.id][1],source:'socialfinder'}}
function conflictsFor(e){if(!calendarState.connected)return [];const candidate=calendarEvent(e);return [...demoBusy,...events.filter(x=>x.id!==e.id&&calendarState.added.includes(x.id)).map(calendarEvent)].filter(x=>intervalsOverlap(candidate,x))}
function calendarBadge(e){if(!calendarState.connected)return '';const conflicts=conflictsFor(e);return `<span class="calendar-badge ${conflicts.length?'conflict':''}">${calendarState.added.includes(e.id)?(conflicts.length?'▣ In demo calendar · Schedule overlap':'▣ In demo calendar'):conflicts.length?'◷ Schedule overlap':'✓ Fits demo schedule'}</span>`}
function calendarEventActions(e){return `<section class="event-calendar"><div class="calendar-section-heading"><span class="calendar-logo" aria-hidden="true">31</span><div><h3>Your time, accounted for</h3><p>Google Calendar · Simulated connection</p></div></div>${calendarState.connected?`<p class="${conflictsFor(e).length?'overlap-text':'check'}">${conflictsFor(e).length?`Overlaps ${conflictsFor(e).map(x=>esc(x.title)).join(', ')} in your fictional schedule.`:'No overlap with your fictional schedule.'}</p><button class="secondary" data-calendar-add="${e.id}">${calendarState.added.includes(e.id)?'Manage calendar entry':'Add to demo calendar'}</button>`:'<p>Preview this event alongside fictional classes and plans.</p><button class="secondary" data-calendar-connect="'+e.id+'">Connect Google Calendar · Demo</button>'}</section>`}
function plansCalendarBanner(){return `<a class="calendar-plan-link" href="#calendar"><span class="calendar-logo" aria-hidden="true">31</span><span><strong>${calendarState.connected?'Your week, all together':'Make room for your plans'}</strong><small>${calendarState.connected?`${calendarState.added.length} campus event${calendarState.added.length===1?'':'s'} in your demo calendar`:'Try a mock Google Calendar connection'}</small></span><span aria-hidden="true">↗</span></a>`}
function calendarPage(){
  const added=events.filter(e=>calendarState.added.includes(e.id));
  return topLine()+`<div class="calendar-intro"><div><span class="eyebrow">GOOD PLANS NEED A LITTLE SPACE</span><h1>Campus life.<br>Meet your calendar.</h1><p>See where a little connection fits between classes.<br>Your week, with room for something good.</p></div><div class="calendar-illustration" aria-hidden="true"><div class="mini-cal"><div>NOVEMBER <span>2026</span></div><section>${['T','W','T','F','S','S',17,18,19,20,21,22].map((n,i)=>`<span class="${i===8?'highlight':''}">${n}</span>`).join('')}</section><p>✧ There’s time for your people.</p></div></div></div><div class="calendar-demo-label">DEMO ONLY · No Google login, permissions, or real calendar changes.</div>${!calendarState.connected?`<section class="connection-card"><span class="calendar-logo large" aria-hidden="true">31</span><div><span class="eyebrow">YOUR WEEK, IN ONE PLACE</span><h2>Connect Google Calendar</h2><p>Try a fictional student schedule. Preview busy times, spot overlaps, and add campus plans without touching a real account.</p><button class="primary" data-calendar-connect="0">Try the mock connection ↗</button></div><ul><li>✓ Five fictional classes & plans</li><li>✓ Clear schedule overlap alerts</li><li>✓ You choose what gets added</li></ul></section><section class="panel calendar-how"><h2>A calmer way to make plans</h2><div><p><b>01 · Connect the demo</b><br>Use the fictional student account. No sign-in needed.</p><p><b>02 · Find a little space</b><br>See how an event fits your sample week.</p><p><b>03 · Make it a plan</b><br>Add an event to this browser’s mock calendar.</p></div></section>`:`<section class="connected-bar"><span class="calendar-logo" aria-hidden="true">31</span><div><strong>Google Calendar <span class="connected-pill">Demo connected</span></strong><small>Jamie Parker · jamie.parker@example.com · Fictional account</small></div><button class="text-button" data-calendar-disconnect>Disconnect demo</button></section><div class="calendar-stats"><div><strong>${demoBusy.length}</strong><span>fictional commitments</span></div><div><strong>${added.length}</strong><span>campus plans added</span></div><div><strong>${events.filter(e=>!conflictsFor(e).length).length}</strong><span>events without overlaps</span></div></div><section class="week-panel"><div class="section-head"><div><h2>A little look at your week</h2><p>November 17–22, 2026 · Central Time</p></div><div class="calendar-legend"><span>● Fictional schedule</span><span>● Campus plans</span></div></div><div class="week-grid">${[17,18,19,20,21,22].map(day=>{const entries=[...demoBusy.filter(x=>x.day===day).map(x=>({...x,source:'google'})),...added.filter(e=>e.day===day).map(calendarEvent)].sort((a,b)=>a.start-b.start);return `<section class="day-column"><h3><span>${['Tue','Wed','Thu','Fri','Sat','Sun'][day-17]}</span>${day}</h3>${entries.length?entries.map(item=>`<div class="agenda-item ${item.source}"><small>${formatMinute(item.start)} – ${formatMinute(item.end)}</small><strong>${esc(item.title)}</strong><p>${esc(item.source==='google'?item.place:item.location)}</p>${item.source==='socialfinder'?`<button class="text-button" data-calendar-add="${item.id}" aria-label="Manage ${esc(item.title)} in demo calendar">Manage ↗</button>${conflictsFor(item).length?'<span class="overlap-text">Schedule overlap</span>':''}`:'<span class="agenda-source">Fictional Google event</span>'}</div>`).join(''):'<div class="open-day">A little breathing room.<br><span>No demo plans yet.</span></div>'}</section>`}).join('')}</div><p class="calendar-footnote">Agenda view · Spacing does not represent duration. Only this fixed sample week is shown.</p></section><div class="section-head"><div><h2>Make space for campus</h2><p>Choose a plan. We’ll show you how it fits.</p></div><a href="#discover">Explore all events ↗</a></div><section class="calendar-picks">${events.map(e=>`<article class="calendar-pick"><div><span class="category">${weekday(e)} · NOV ${e.day}</span><h3>${e.title}</h3><p>${e.time} CT</p>${calendarBadge(e)}</div><button class="secondary" data-calendar-add="${e.id}">${calendarState.added.includes(e.id)?'Manage':'Add event'}</button></article>`).join('')}</section>`}`;
}

let calendarReturnFocus=null,calendarReturnSelector=null,pendingCalendarEvent=null;
function calendarModal(){return document.getElementById('calendar-dialog')}
function openCalendarModal(html){const modal=calendarModal();if(!modal.open){calendarReturnFocus=document.activeElement;calendarReturnSelector=null;for(const key of ['data-calendar-add','data-calendar-connect','data-calendar-disconnect'])if(calendarReturnFocus?.hasAttribute(key)){const value=calendarReturnFocus.getAttribute(key);calendarReturnSelector=value?`[${key}="${value}"]`:`[${key}]`;break}}modal.innerHTML=`<button class="close" data-calendar-close aria-label="Close calendar preview">×</button><div class="calendar-modal-body">${html}</div>`;const heading=modal.querySelector('h2');heading.id='calendar-dialog-title';heading.tabIndex=-1;if(!modal.open)modal.showModal();heading.focus()}
function closeCalendarModal(){calendarModal().close()}
function showCalendarConnect(id=0){pendingCalendarEvent=id||null;openCalendarModal(`<span class="demo-step">SIMULATED CONNECTION · 1 OF 2</span><span class="calendar-logo large" aria-hidden="true">31</span><h2>A preview, not a sign-in.</h2><p>Try Google Calendar with a fictional student account. You won’t enter a password or grant access to Google.</p><div class="mock-account"><span class="avatar">JP</span><div><strong>Jamie Parker</strong><small>jamie.parker@example.com · Fictional</small></div></div><button class="primary" data-calendar-next>Continue with demo account ↗</button><button class="text-button" data-calendar-close>Cancel</button>`)}
function showCalendarConsent(){openCalendarModal(`<span class="demo-step">SIMULATED CONNECTION · 2 OF 2</span><h2>Your calendar, your choice.</h2><p>This preview loads five fictional commitments and lets you add campus events to a mock calendar in this browser.</p><ul class="consent-list"><li>View a fictional schedule for November 17–22.</li><li>Check event times for overlaps.</li><li>Add or remove only the demo plans you choose.</li></ul><div class="notice">No Google permissions are requested. No real account is connected. Disconnecting clears this mock calendar but keeps your saved events and RSVPs.</div><label class="calendar-consent"><input type="checkbox" id="calendar-consent">I understand this is a simulation using fictional data.</label><div class="dialog-actions"><button class="primary" id="calendar-confirm-connect" disabled>Connect demo calendar</button><button class="secondary" data-calendar-back>Back</button></div>`)}
function showCalendarEntry(id){const e=events.find(x=>x.id===id);if(!e)return;if(!calendarState.connected){showCalendarConnect(id);return}pendingCalendarEvent=id;const added=calendarState.added.includes(id),conflicts=conflictsFor(e);openCalendarModal(`<span class="demo-step">${added?'MANAGE DEMO EVENT':'ADD TO DEMO CALENDAR'}</span><h2>${e.title}</h2><p>${weekday(e)}, November ${e.day}, 2026<br>${e.time} CT · ${e.location}</p><div class="calendar-destination"><span class="calendar-logo" aria-hidden="true">31</span><div><strong>Jamie’s campus plans</strong><small>Fictional Google Calendar · Browser-local demo</small></div></div>${conflicts.length?`<div class="conflict-panel"><strong>Heads up: your plans overlap.</strong>${conflicts.map(c=>`<p>${esc(c.title)}<br>${formatMinute(c.start)}–${formatMinute(c.end)} CT</p>`).join('')}<small>${e.drop?'This event allows drop-ins. You can still choose to add its full scheduled time.':'This event expects full-session attendance. Consider another event if you cannot stay.'}</small></div>`:'<div class="notice">✓ This event fits your fictional schedule.</div>'}${added?'<p class="check">✓ Already in your demo calendar. No duplicate will be added.</p>':conflicts.length?'<label class="calendar-consent"><input type="checkbox" id="calendar-overlap-consent">Add the full event time despite this overlap.</label>':''}<div class="dialog-actions">${added?`<button class="secondary" data-calendar-remove="${id}">Remove from demo calendar</button>`:`<button class="primary" data-calendar-confirm-add="${id}" ${conflicts.length?'disabled':''}>Add to demo calendar</button>`}<button class="text-button" data-calendar-close>Cancel</button></div><p class="calendar-footnote">No real calendar entry or RSVP is created.</p>`)}
function refreshAfterCalendar(){render();if(dialog.open&&activeEvent)showEvent(activeEvent)}
document.addEventListener('click',event=>{
  const button=event.target.closest('button');if(!button)return;
  if(button.hasAttribute('data-calendar-connect'))showCalendarConnect(Number(button.dataset.calendarConnect));
  if(button.hasAttribute('data-calendar-next'))showCalendarConsent();
  if(button.hasAttribute('data-calendar-back'))showCalendarConnect(pendingCalendarEvent||0);
  if(button.hasAttribute('data-calendar-close'))closeCalendarModal();
  if(button.id==='calendar-confirm-connect'&&document.getElementById('calendar-consent')?.checked){calendarState.connected=true;persistCalendar();refreshAfterCalendar();if(pendingCalendarEvent){showCalendarEntry(pendingCalendarEvent);if(!calendarStorageOK)calendarModal().querySelector('.calendar-modal-body').insertAdjacentHTML('afterbegin','<p class="notice" role="status">Connected for this visit only. Browser storage is unavailable; this connection will not be saved.</p>')}else{closeCalendarModal();location.hash='calendar';calendarNotice('Demo calendar connected. Only fictional data was loaded.')}}
  if(button.hasAttribute('data-calendar-add'))showCalendarEntry(Number(button.dataset.calendarAdd));
  if(button.hasAttribute('data-calendar-confirm-add')){
    const id=Number(button.dataset.calendarConfirmAdd),e=events.find(x=>x.id===id);
    if(!e||!calendarState.connected||conflictsFor(e).length&&!document.getElementById('calendar-overlap-consent')?.checked)return;
    if(!calendarState.added.includes(id))calendarState.added.push(id);
    persistCalendar();refreshAfterCalendar();closeCalendarModal();calendarNotice('Added to your demo calendar. No real Google Calendar changes.');
  }
  if(button.hasAttribute('data-calendar-remove')){calendarState.added=calendarState.added.filter(id=>id!==Number(button.dataset.calendarRemove));persistCalendar();refreshAfterCalendar();closeCalendarModal();calendarNotice('Removed from demo calendar. Saved events and RSVPs are unchanged.')}
  if(button.hasAttribute('data-calendar-disconnect'))openCalendarModal(`<span class="demo-step">DISCONNECT DEMO</span><h2>Clear this mock connection?</h2><p>This removes the fictional connection and ${calendarState.added.length} calendar ${calendarState.added.length===1?'entry':'entries'} from this browser. Your saved events, RSVPs and preferences stay as they are.</p><div class="dialog-actions"><button class="primary" data-calendar-confirm-disconnect>Disconnect & clear demo calendar</button><button class="secondary" data-calendar-close>Keep connected</button></div>`);
  if(button.hasAttribute('data-calendar-confirm-disconnect')){resetCalendar();refreshAfterCalendar();closeCalendarModal();calendarNotice('Demo calendar disconnected. Your other plans are unchanged.')}
});
document.addEventListener('change',event=>{if(event.target.id==='calendar-consent')document.getElementById('calendar-confirm-connect').disabled=!event.target.checked;if(event.target.id==='calendar-overlap-consent')calendarModal().querySelector('[data-calendar-confirm-add]').disabled=!event.target.checked});
document.addEventListener('DOMContentLoaded',()=>{const modal=calendarModal();modal.addEventListener('close',()=>{const target=calendarReturnFocus?.isConnected?calendarReturnFocus:dialog.open?dialog.querySelector('[data-calendar-add], [data-calendar-connect]'):(calendarReturnSelector?main.querySelector(calendarReturnSelector):null)||main.querySelector('[data-calendar-connect], [data-calendar-disconnect]')||main;target?.focus()});modal.addEventListener('click',event=>{if(event.target===modal){const r=modal.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)modal.close()}})});
